from AlgorithmImports import *
import math


class IndependentDailyStrategies(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            "SPY": self.add_equity("SPY", Resolution.DAILY).symbol,
            "AAPL": self.add_equity("AAPL", Resolution.DAILY).symbol,
            "IBM": self.add_equity("IBM", Resolution.DAILY).symbol,
            "BAC": self.add_equity("BAC", Resolution.DAILY).symbol,
            "AIG": self.add_equity("AIG", Resolution.DAILY).symbol
        }

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        # Keep market-state calculations current whenever their own bar exists.
        if data.bars.contains_key(self.symbols["SPY"]):
            self.spy_closes.add(float(data.bars[self.symbols["SPY"]].close))

        if data.bars.contains_key(self.symbols["AAPL"]):
            aapl_bar = data.bars[self.symbols["AAPL"]]
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

            if aapl_bar.close < aapl_bar.open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Skip all rule evaluation if any subscribed ticker is missing today.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        # Do not trade until all rule inputs are fully formed.
        if not self.spy_closes.is_ready or not self.aapl_rsi.is_ready:
            return

        spy_bar = data.bars[self.symbols["SPY"]]
        aapl_bar = data.bars[self.symbols["AAPL"]]

        spy_close_today = self.spy_closes[0]
        spy_close_yesterday = self.spy_closes[1]

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        # Evaluate sells before buys.
        if self.strategy_a_lot > 0:
            if spy_close_yesterday >= spy_sma_yesterday and spy_close_today < spy_sma_today:
                self.market_order(self.symbols["SPY"], -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_lot)
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if spy_close_yesterday <= spy_sma_yesterday and spy_close_today > spy_sma_today:
                quantity = int(math.floor(
                    (self.portfolio.total_portfolio_value * 0.40) / spy_bar.close
                ))
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(math.floor(20_000 / aapl_bar.close))
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_lot = quantity
