from AlgorithmImports import *


class IndependentTwoSlotStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.lots = {"A": 0, "B": 0}
        self.pending = {"A": False, "B": False}

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_days = 0

    def OnData(self, data: Slice) -> None:
        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)
        indicators_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        )

        if all_bars_present and indicators_ready:
            spy_close = float(data.Bars[self.spy].Close)
            aapl_close = float(data.Bars[self.aapl].Close)

            # Sells are evaluated before buys.
            if (
                self.lots["A"] > 0
                and not self.pending["A"]
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < float(self.spy_sma.Current.Value)
            ):
                self._submit_order("A", self.spy, -self.lots["A"])

            if (
                self.lots["B"] > 0
                and not self.pending["B"]
                and float(self.aapl_rsi.Current.Value) > 60
            ):
                self._submit_order("B", self.aapl, -self.lots["B"])

            if (
                self.lots["A"] == 0
                and not self.pending["A"]
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > float(self.spy_sma.Current.Value)
            ):
                quantity = int(
                    0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
                )
                if quantity > 0:
                    self._submit_order("A", self.spy, quantity)

            if (
                self.lots["B"] == 0
                and not self.pending["B"]
                and self.aapl_red_days >= 3
                and float(self.Portfolio.Cash) >= 20_000
            ):
                quantity = int(20_000 / aapl_close)
                if quantity > 0:
                    self._submit_order("B", self.aapl, quantity)

        if data.Bars.ContainsKey(self.spy):
            self.previous_spy_close = float(data.Bars[self.spy].Close)
            if self.spy_sma.IsReady:
                self.previous_spy_sma = float(self.spy_sma.Current.Value)

    def _submit_order(self, slot: str, symbol: Symbol, quantity: int) -> None:
        self.pending[slot] = True
        self.MarketOrder(symbol, quantity, False, slot)

    def OnOrderEvent(self, order_event: OrderEvent) -> None:
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None or order.Tag not in self.lots:
            return

        slot = order.Tag

        if order_event.FillQuantity != 0:
            self.lots[slot] = max(0, self.lots[slot] + order_event.FillQuantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.pending[slot] = False
